      const G=idx.map(pc=>Object.assign(S.span(0,1),{dur:A.pcW[pc]/T,pcc:A.pcCol(pc,m0)})); const keys=[0.6,0.34,0.74].map(k=>_rkClamp(k+(S.regAll-0.5)*0.2,0,1));
