  const along=(t,ang,off)=>({x:cx+Math.cos(ang)*(t-0.5)*D*1.3+Math.cos(ang+1.5708)*off, y:cy+Math.sin(ang)*(t-0.5)*D*1.3+Math.sin(ang+1.5708)*off});
