    if(o.composer){ cx.fillStyle=SOFT; const t=_fitText(cx,o.composer,bw,Math.round(Wf*0.02),Math.round(Wf*0.012),sans); cx.fillText(t,Wf/2,y); y+=Math.round(Wf*0.034); }
