    if(_il){ cx.fillStyle=GOLD; const t=_fitText(cx,_il,bw,Math.round(Wf*0.025),Math.round(Wf*0.014),serifI5); cx.fillText(t,Wf/2,y); y+=Math.round(Wf*0.03); }
