  const _tintOwn = draftOwnerRef.current;
  const _favTintKey = (f)=> !f ? null : f.kind==='img' ? 'image' : f.src==='compose' ? 'compose' : f.src==='mic' ? 'mic' : f.src==='image' ? 'mfi' : f.mood ? 'mood' : (f.src==='midi'||f.src==='audio'||f.src==='score') ? 'music' : null;
